const mongoose = require("mongoose");
const User = require("./models/User");
const Vet = require("./models/Vet");
const Pet = require("./models/Pet");
const Appointment = require("./models/Appointment");
const Consultation = require("./models/Consultation");
const Prescription = require("./models/Prescription");
const ChatMessage = require("./models/ChatMessage");

const mongoURI = "mongodb://127.0.0.1:27017/gemini_api";

async function seed() {
  try {
    await mongoose.connect(mongoURI);
    console.log("Connected to MongoDB");

    // Clear all collections
    await Promise.all([
      User.deleteMany({}),
      Vet.deleteMany({}),
      Pet.deleteMany({}),
      Appointment.deleteMany({}),
      Consultation.deleteMany({}),
      Prescription.deleteMany({}),
      ChatMessage.deleteMany({})
    ]);
    console.log("Cleared existing records.");

    // Create 4 Users
    const users = await User.insertMany([
      { name: "Rahul Verma", email: "rahul@example.com", phone: "9876543211", password: "password123", role: "owner" },
      { name: "Priya Sharma", email: "priya@example.com", phone: "9876543212", password: "password123", role: "owner" },
      { name: "Amit Kumar", email: "amit@example.com", phone: "9876543213", password: "password123", role: "owner" },
      { name: "Sneha Reddy", email: "sneha@example.com", phone: "9876543214", password: "password123", role: "owner" }
    ]);

    // Create 4 Pets (linked to Users)
    const pets = await Pet.insertMany([
      { ownerId: users[0]._id, ownerName: users[0].name, ownerEmail: users[0].email, ownerPhone: users[0].phone, name: "Sheru", type: "Dog", breed: "Indian Pariah", age: 3, weight: 15, gender: "Male" },
      { ownerId: users[1]._id, ownerName: users[1].name, ownerEmail: users[1].email, ownerPhone: users[1].phone, name: "Luna", type: "Dog", breed: "Golden Retriever", age: 2, weight: 22, gender: "Female" },
      { ownerId: users[2]._id, ownerName: users[2].name, ownerEmail: users[2].email, ownerPhone: users[2].phone, name: "Milo", type: "Cat", breed: "Calico", age: 4, weight: 5, gender: "Male" },
      { ownerId: users[3]._id, ownerName: users[3].name, ownerEmail: users[3].email, ownerPhone: users[3].phone, name: "Bruno", type: "Dog", breed: "German Shepherd", age: 5, weight: 30, gender: "Male" }
    ]);

    // Create 4 Vets
    const vets = await Vet.insertMany([
      { name: "Dr. Ananya Sharma", email: "ananya@example.com", vciNumber: "VCI-2024-8891", password: "password123", specialization: ["General Practice", "Surgery"], clinicName: "PawsCare Pet Hospital", city: "Bengaluru", consultationFee: 499, experienceYears: 8 },
      { name: "Dr. Vikram Singh", email: "vikram@example.com", vciNumber: "VCI-2024-9922", password: "password123", specialization: ["Dermatology"], clinicName: "Healthy Paws Clinic", city: "Delhi", consultationFee: 599, experienceYears: 12 },
      { name: "Dr. Neha Gupta", email: "neha@example.com", vciNumber: "VCI-2024-7733", password: "password123", specialization: ["Dental", "General Practice"], clinicName: "Happy Tails Vet", city: "Mumbai", consultationFee: 450, experienceYears: 5 },
      { name: "Dr. Rajesh Patel", email: "rajesh@example.com", vciNumber: "VCI-2024-6644", password: "password123", specialization: ["Orthopedics", "Surgery"], clinicName: "Care Vet Clinic", city: "Ahmedabad", consultationFee: 700, experienceYears: 15 }
    ]);

    // Create 4 Appointments (linked to Vet, User, Pet)
    const appointments = await Appointment.insertMany([
      { vetId: vets[0]._id, ownerId: users[0]._id, ownerName: users[0].name, petId: pets[0]._id, petName: pets[0].name, petSpecies: pets[0].type, date: "2026-09-05", time: "10:00 AM", consultationType: "Virtual Telehealth Call", status: "upcoming", reason: "Annual checkup", fee: 499 },
      { vetId: vets[1]._id, ownerId: users[1]._id, ownerName: users[1].name, petId: pets[1]._id, petName: pets[1].name, petSpecies: pets[1].type, date: "2026-09-02", time: "02:30 PM", consultationType: "In-Person Clinic Visit", status: "completed", reason: "Vaccination", fee: 599 },
      { vetId: vets[2]._id, ownerId: users[2]._id, ownerName: users[2].name, petId: pets[2]._id, petName: pets[2].name, petSpecies: pets[2].type, date: "2026-09-04", time: "11:30 AM", consultationType: "Virtual Telehealth Call", status: "completed", reason: "Skin allergy", fee: 450 },
      { vetId: vets[3]._id, ownerId: users[3]._id, ownerName: users[3].name, petId: pets[3]._id, petName: pets[3].name, petSpecies: pets[3].type, date: "2026-09-10", time: "04:00 PM", consultationType: "In-Person Clinic Visit", status: "upcoming", reason: "Dental cleaning", fee: 700 }
    ]);

    // Create 4 Consultations (linked to Vet, User, Pet, Appointment)
    const consultations = await Consultation.insertMany([
