if (!date || !time || !type) {
  alert("Please select date, time, and type of consultation.");
  return;
}

if (!selectedPetId) {
  alert("Please select a pet for this consultation.");
  return;
}

const storedUser = localStorage.getItem('currentUser');
if (!storedUser) {
  alert("Please login to book an appointment");
  navigate('/login');
  return;
}

setBookingLoading(true);
try {
  const user = JSON.parse(storedUser);
  const selectedPet = pets.find(p => p._id === selectedPetId);

  const payload = {
    vetId: vet._id,
    vetName: vet.name,
    vetSpecialization: vet.qualification,
    ownerId: user._id || "guest",
    ownerName: user.name || "Pet Parent",
    ownerPhone: user.phone || "+91 00000 00000",
    petId: selectedPet._id,
    petName: selectedPet.name,
    petSpecies: selectedPet.species,
    petBreed: selectedPet.breed,
    petAge: selectedPet.age,
    petWeight: selectedPet.weight,
    petSex: selectedPet.sex,
    date: date,
    time: time,
    consultationType: type,
    reasonForVisit: reason,
    fee: vet.consultationFee || 499,
    status: 'upcoming'
  };

  // 1. Create Appointment first
  const apptRes = await fetch('http://localhost:5000/api/appointments', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });

  const apptJson = await apptRes.json();
  if (!apptRes.ok || !apptJson.success) {
    throw new Error(apptJson.message || "Failed to create appointment");
  }

  // 2. Create Consultation linked to the Appointment
  const consultPayload = { ...payload, appointmentId: apptJson.appointment._id };
  const res = await fetch('http://localhost:5000/api/consultations', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(consultPayload)
  });

  const json = await res.json();

  if (res.ok && json.success) {
    alert(`Consultation with ${vet.name} confirmed!\nDate: ${date}\nTime: ${time}`);
    navigate('/appointments');
  } else {
    alert(json.message || "Failed to book consultation");
  }
} catch (err) {
  alert("Error booking consultation: " + err.message);
} finally {
  setBookingLoading(false);
}

